INSERT INTO missions (id, domain, title, skill, email_subject, win_message, note) VALUES (1, 'WORDS', 'Send the message you''ve been putting off.', 'Tell AI exactly the tone you need — then ask for two versions so you stay the decision-maker.', 'The message you''ve been avoiding? Gone in 5 minutes.', 'That message is out of your head and into the world. 🎉', NULL);
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (1, 'shop', 'The supplier who keeps delivering late', 'You run a small shop. Your supplier has been late three times this month and it''s costing you customers. You need to push back firmly — without burning a relationship you depend on. You''ve drafted this message in your head for a week.', 'I run a small shop and my supplier has delivered late 3 times this month: [briefly describe what happened]. I need a short message that is firm about the problem but keeps the relationship warm, and asks for [what you want to happen]. Keep it under 120 words, no corporate jargon. Give me 2 versions: one firmer, one friendlier.', 'You told the AI who you are, what happened, the tone you need, a length limit, and asked for two versions to choose from. Those five ingredients turn a vague draft into exactly your voice.');
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (1, 'parent', 'The teacher email you keep rewriting', 'Your kid is struggling in one class and you''ve started an email to the teacher four times. Too pushy? Too soft? You want to be taken seriously as a partner, not flagged as "that parent."', 'I''m a parent writing to my child''s teacher. The situation: [what''s going on with your kid]. I want to come across as a supportive partner, not a complainer, and I''d like to ask for [what you''re hoping the teacher will do]. Write a warm, respectful email under 150 words, then tell me in one line what tone it strikes.', 'Naming the fear ("not a complainer") is the trick — AI is remarkably good at threading a tone needle when you tell it exactly which needle. The one-line tone check makes the AI grade its own work.');
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (1, 'office', 'The delay you have to tell your manager about', 'The project is going to be late. Not disastrously — but you''ve rewritten the message to your manager five times, bouncing between over-apologizing and sounding like you don''t care. It''s now two days overdue as a message, which is worse than the delay itself.', 'I need to tell my manager that [project] will be [X days] late because [honest reason]. Write a short message that owns the delay without groveling, gives the new realistic date, and offers one concrete step I''m taking to prevent a repeat. Under 100 words, professional but human. Give me 2 versions: one more formal, one more direct.', 'Own it, new date, prevention step — that three-part shape is what good managers actually want, and AI assembles it without the emotional spiral. The "no groveling" instruction matters: apology inflation reads worse than the delay.');
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (1, 'job', 'Following up without sounding desperate', 'You interviewed nine days ago. Silence. Everyone says "just follow up!" but every draft you write sounds either needy or robotic. This message could genuinely matter.', 'I interviewed for a [job title] role 9 days ago and haven''t heard back. Write a short follow-up email that sounds confident and warm, not desperate. Mention one specific thing from my interview: [something you discussed]. Under 100 words. Then give me a version that''s 30% more casual so I can pick.', 'The one specific detail from your interview is what separates a memorable follow-up from spam — and asking for a "more casual" second version teaches you to steer tone like a dial, not a guess.');
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (1, 'retiree', 'The insurance letter that makes no sense', 'A letter from your insurance company arrived and it might as well be in another language. You need to reply by Friday, and you refuse to pay for something you don''t understand.', 'I''m going to paste a letter from my insurance company. First, explain what it actually says in plain language, like you''d explain to a friend. Then tell me the one thing they''re really asking me to do, and draft a short reply asking [your question] in a way they must answer clearly. Here''s the letter: [paste it]', '"Explain it like you''d explain to a friend" flips AI from formal to human instantly. And making it identify "the one thing they really want" cuts through pages of fine print in seconds.');
INSERT INTO challenge_rounds (mission_id, round, task, prompt_a, prompt_b, winner, verdict) VALUES (1, 1, 'a birthday message for a coworker they barely know.', 'Write a birthday message for my coworker.', 'Write a short, warm birthday message for a coworker I don''t know well. We only ever chat about coffee and the office plants. Make it friendly but not over-the-top, one or two sentences.', 'b', 'B gave the AI the relationship, the shared ground, and the tone limit. A got a generic greeting card; B got something that sounds like an actual human who sits ten feet away.');
INSERT INTO challenge_rounds (mission_id, round, task, prompt_a, prompt_b, winner, verdict) VALUES (1, 2, 'both got a wrong answer and wanted a better one.', 'That''s not what I meant. My budget is tight this month, so make the meal plan cheaper — swap anything fancy for basics like eggs, beans, or frozen veg.', 'Wrong. Try again.', 'a', 'A treats AI like a helpful intern: what missed, why, what to do instead — fixed in one go. B rerolls the dice and gets different-flavored wrong. The #1 beginner unlock is how you steer the *second* prompt.');
INSERT INTO challenge_rounds (mission_id, round, task, prompt_a, prompt_b, winner, verdict) VALUES (1, 3, 'improving a paragraph they''d written.', 'Make this paragraph better: [paragraph]', 'Here''s my paragraph: [paragraph]. Give me 3 versions — one more confident, one shorter, one more casual — and tell me in one line what you changed in each.', 'b', '"Better" forces AI to guess what better means — and its guess overwrites your voice. Labeled options keep you the decision-maker.');
INSERT INTO challenge_rounds (mission_id, round, task, prompt_a, prompt_b, winner, verdict) VALUES (1, 4, 'planning a big family reunion.', 'Help me plan a family reunion for about 30 people in August. We need a venue idea, a food plan for mixed diets including my vegan niece, activities for kids 4–12 and grandparents, a budget around $800, a rain backup, and a schedule from 11am to 6pm.', 'Help me plan a family reunion. Before you write any plan, ask me the five most important questions, one at a time.', 'b', 'A looks like the "perfect prompt" — but you can only list what you''ve already thought of, and the plan inherits your blind spots. B turns AI into an interviewer. For big fuzzy tasks: let AI ask first.');
INSERT INTO missions (id, domain, title, skill, email_subject, win_message, note) VALUES (2, 'MONEY', 'Lower a bill without the awkwardness.', 'Give AI the goal and the facts — it writes your script and preps you for the pushback.', 'Today''s mission pays for itself (literally).', 'Money conversations stop being scary when you arrive with a script. 🎉', NULL);
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (2, 'shop', 'The card fees that keep creeping up', 'Your card processor''s fee has quietly crept from 2.3% to 2.9%. On your revenue that''s real money every month — but calling to negotiate feels confrontational, so it stays on the someday list.', 'I run a small shop. My card processor now charges me [your current rate/fees]. A competitor advertises [their rate]. Write me a short, friendly phone script to ask for a better rate: confident, not aggressive, mentions I''m prepared to switch, and includes exactly what to say if they say no. Then list the 2 questions they''ll most likely ask me, with suggested answers.', 'You gave AI a goal (lower rate), leverage (competitor''s offer), and a tone. Asking for the likely pushback questions means you walk into the call prepared instead of hopeful.');
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (2, 'parent', 'The internet bill that grew while nobody was looking', 'Your family''s internet-and-phone bundle has gone up twice since you signed. Everyone says "just call and ask for the promo rate" — but you never know what to actually say when they start reading the fine print at you.', 'My family''s internet + phone bill is [amount] with [company], up from [old amount]. New customers get [their advertised deal]. Write me a short, polite phone script asking for a better rate: mention I''ve been a customer [X years], I''d rather stay, and I''m ready to compare options. Include what to say if the first agent says no, and the one sentence that gets me to the retention department.', 'Companies have discounts reserved for people who ask in the right order: loyalty first, comparison second, retention team third. The script encodes that order so you don''t improvise while someone reads terms at you.');
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (2, 'office', 'The insurance renewal that jumped for no reason', 'Your car insurance renewal arrived 22% higher. Same car, same record, no claims. You know you should push back or shop around — but comparing policies feels like homework, so last year you just paid it.', 'My car insurance renewal went from [old price] to [new price] with no claims and no changes. I have a quote from [competitor] for [amount]. Write a short, firm-but-polite message to my insurer asking them to review my premium, mentioning my clean record and the competing quote — and asking directly: ''What is your best rate to keep me?'' Keep it under 100 words.', '"What is your best rate to keep me?" is a direct question that''s hard to deflect — much stronger than "is there anything you can do?" AI is good at being politely direct in ways we chicken out of ourselves.');
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (2, 'job', 'The offer you''re afraid to negotiate', 'You got the offer — great news. It''s a bit under what you hoped, and everyone says "always negotiate"… but the fear is real: what if pushing back sours it? You need words that ask for more without risking the yes.', 'I received a job offer: [role] at [salary]. Based on my research, the market range is [range], and I was hoping for [target]. Write a short, warm counter-offer email that expresses genuine excitement, asks for [target], and backs it with my two strongest points: [strength 1] and [strength 2]. No apologies, no ultimatums, under 120 words. Then give me the one confident sentence to say if they phone me instead of replying.', 'The riskiest part of negotiating is tone — grateful but not apologetic, firm but not adversarial. Feeding AI your strengths and the market range keeps the ask grounded in facts, and "no apologies, no ultimatums" removes the two classic ways these emails go wrong.');
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (2, 'retiree', 'The TV bill that assumes you won''t call', 'Your cable bill has gone up three times in two years. They''re counting on it being too much hassle to do anything about — long menus, hold music, agents reading scripts. Time to arrive with a better script than theirs.', 'I''ve been a [company] TV customer for [X years]. My bill is now [amount], up from [old amount]. Write me a short, courteous phone script asking for my bill to be reduced: mention my loyalty, that I don''t watch most channels, and that I''m considering cancelling for a streaming service. Include what to say when they offer a tiny discount first, and remind me to write down the agent''s name and the new price before hanging up.', 'The first offer is never the real offer — the script helps you politely decline round one and stay comfortable in the pause that follows. Noting the agent''s name turns a vague promise into a record.');
INSERT INTO challenge_rounds (mission_id, round, task, prompt_a, prompt_b, winner, verdict) VALUES (2, 1, 'asking for a gym discount.', 'Write me something to get a discount on my gym membership.', 'My gym is $59/month; the one down the street charges $39. I''ve been a member 3 years. Write a short, friendly message asking them to match $45, and mention I''d rather stay.', 'b', 'Numbers are leverage, and AI can''t invent yours. A discount request without facts is just a wish with a stamp on it.');
INSERT INTO challenge_rounds (mission_id, round, task, prompt_a, prompt_b, winner, verdict) VALUES (2, 2, 'bank charged surprise fees.', 'Write a complaint email to my bank about fees.', 'Write a firm but polite email to my bank: they charged two $35 overdraft fees on the same day ([dates]). I''ve been a customer 8 years with no previous overdrafts. Ask them to refund both as a courtesy — and ask which account setting prevents this happening again.', 'b', 'One clear ask plus a prevention question turns a rant into a result. Complaints vent; requests convert.');
INSERT INTO challenge_rounds (mission_id, round, task, prompt_a, prompt_b, winner, verdict) VALUES (2, 3, 'cancelling a streaming service.', 'Write a phone script to cancel my streaming service and get a retention offer. Five sentences max.', 'Write a phone script to cancel my streaming service. Then list the 3 offers they''re most likely to make, and tell me which is actually the best deal and why.', 'b', 'A is a decent prompt — short, specific. But negotiation is a two-player game, and B is the only one that prepared for the other player''s moves. Anticipation beats polish.');
INSERT INTO challenge_rounds (mission_id, round, task, prompt_a, prompt_b, winner, verdict) VALUES (2, 4, 'cutting monthly costs.', 'I want to save money. Make me a complete savings plan: budgeting method, spending categories, weekly review routine, and savings targets for the next 6 months.', 'Here are my last 3 phone bills: [paste]. Find charges I don''t recognize or don''t need, and rank them by monthly savings if removed.', 'b', 'A looks impressively thorough — but it runs on what you *remember* about your spending, and memory is the whole problem. B hands AI a real document and lets it spot what you''ve stopped seeing. Paste beats describe.');
INSERT INTO missions (id, domain, title, skill, email_subject, win_message, note) VALUES (3, 'TIME', 'Turn what you already have into this week''s plan.', 'Hand AI your messy reality — a quick list, exactly as it is — and let it do the organizing.', 'A week of decisions, made in 5 minutes.', 'A week of decisions, made in five minutes. 🎉', NULL);
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (3, 'parent', 'Five dinners, two picky kids, one tired human', 'It''s 5pm and the daily question is back: what''s for dinner? Multiply by five school nights, subtract the four foods your kids actually eat, and it''s the most exhausting small problem in your week. Your fridge already holds the answer — it just needs organizing.', 'Here''s what''s in my kitchen right now: [list it fast — don''t tidy the list, just type what you see]. My kids will eat [the honest short list] and refuse [the refusals]. Plan 5 weeknight dinners using mostly what I have, each under 30 minutes. Mark which need something from the store, and put those items in one short shopping list at the end.', 'The magic instruction is "don''t tidy the list." AI is built to organize mess — the more honestly messy your input, the more useful the plan. You skip the part of planning that makes planning miserable.');
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (3, 'shop', 'Feed yourself like someone who doesn''t stand in a shop all day', 'Six shop days a week means dinner is whatever''s fastest at 9pm — expensive, unhealthy, and honestly a bit sad. One Sunday hour of batch cooking would fix it, if figuring out what to cook didn''t feel like a second job.', 'I work long days in my shop, 6 days a week, and get home around 8:30pm. Plan me a Sunday batch-cooking session: 1 hour max, using [what''s in your kitchen + budget], producing 5 grab-and-heat dinners. Give me the cooking order so everything overlaps efficiently — start with what takes longest, and tell me exactly what to do while each thing cooks.', 'The unlock is asking for the cooking *order*, not just recipes. "What do I do while the rice cooks?" is the difference between one efficient hour and three chaotic ones — cooking is a schedule, and AI is excellent at schedules.');
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (3, 'office', 'Stop buying the $15 lunch you don''t even like', 'Every workday, noon arrives and you''re queueing for a lunch that costs too much and disappoints anyway. That''s ~$75 a week for mediocrity. Fifteen minutes on Sunday could take back most of it — if the planning weren''t the annoying part.', 'I buy lunch every workday (~[amount]/week) and want to prep instead. I have [15–30] minutes on Sunday and these things in my kitchen: [quick list]. Plan 4 grab-and-go lunches that survive a desk fridge, don''t need reheating (or reheat well), and won''t bore me by Thursday. Include the 5-item-max shopping list and how much I''ll save this week.', 'Constraints are the whole prompt: time cap, desk-fridge-proof, boredom-proof, tiny shopping list. Every constraint you name is a bad outcome you''ve prevented — and that works far beyond lunches.');
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (3, 'job', 'Eat well on a job-hunt budget', 'Job hunting is a full-time job that doesn''t pay. The food budget is tight, delivery is a trap, and decision fatigue from applications leaves nothing for meal decisions. You need a week of cheap, decent eating planned in one shot.', 'My grocery budget this week is [amount]. Here''s what I already have: [quick list]. Plan 7 dinners and easy lunches that fit the budget, reuse ingredients across meals so nothing is wasted, and take under 30 minutes each. Give me one shopping list organized by supermarket aisle, with a running cost estimate.', '"Reuse ingredients across meals" is the instruction that makes a small budget behave like a bigger one — AI plans the overlaps (tonight''s roast chicken is tomorrow''s fried rice) that we don''t have patience to design ourselves.');
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (3, 'retiree', 'Cooking for two without cooking for six', 'Forty years of cooking for a full table is a hard habit to shrink. Pots are too big, leftovers multiply, and half the vegetable drawer goes soft before it''s used. The goal isn''t new recipes — it''s right-sizing the week.', 'We''re a household of two. Here''s what''s in the fridge and pantry: [quick honest list, including things about to go soft]. Plan this week''s dinners for two — proper portions, no mountain of leftovers — starting with whatever needs using first. If something will still be left over, tell me exactly what tomorrow''s lunch does with it.', '"Start with whatever needs using first" turns AI into the anti-waste planner — it sequences the week around your vegetable drawer''s deadlines. Pre-assigning leftovers to tomorrow''s lunch is how they get eaten instead of archived.');
INSERT INTO challenge_rounds (mission_id, round, task, prompt_a, prompt_b, winner, verdict) VALUES (3, 1, 'tonight''s dinner.', 'What should I make for dinner?', 'I have chicken thighs, half a cabbage, rice, eggs, and 25 minutes. What can I make? Give me 3 options, fastest to fanciest.', 'b', 'A gets you someone else''s dinner. B gets you *yours* — inventory plus a time limit is all it takes.');
INSERT INTO challenge_rounds (mission_id, round, task, prompt_a, prompt_b, winner, verdict) VALUES (3, 2, 'Saturday errands.', 'Plan my Saturday errands efficiently: pharmacy, hardware store, groceries, post office, shoe pickup. The post office closes at noon and the roast needs to be in the oven by 4.', 'Plan my Saturday errands efficiently: pharmacy, hardware store, groceries, post office, shoe pickup.', 'a', 'Same list, one difference: deadlines. The closing time and the roast aren''t details — they *are* the plan. Constraints first, efficiency second.');
INSERT INTO challenge_rounds (mission_id, round, task, prompt_a, prompt_b, winner, verdict) VALUES (3, 3, 'organizing a chaotic week.', 'Organize my week. Here''s everything on my plate, exactly as it''s written in my notes app, typos and all: [paste].', 'Organize my week. First give me a clean template to fill in, so I can type up my tasks properly and send them back.', 'a', 'B feels responsible — and it''s procrastination wearing a helmet. You don''t need to tidy your mess for the machine; organizing mess is the machine''s job. Paste it raw.');
INSERT INTO challenge_rounds (mission_id, round, task, prompt_a, prompt_b, winner, verdict) VALUES (3, 4, 'building a morning routine.', 'Make me a morning routine like successful CEOs use.', 'Design a realistic morning for someone who hits snooze twice, has 40 minutes, and needs to leave fed and sane. Tell me what to prepare the night before — and what to cut first when I''m running late.', 'b', 'Plans built on your real behavior beat plans built on someone else''s highlight reel. And "what to cut when late" plans for failure — which is exactly what makes routines survive contact with Monday.');
INSERT INTO missions (id, domain, title, skill, email_subject, win_message, note) VALUES (4, 'WORK', 'Practice the conversation you''re dreading — before it''s real.', 'Ask AI to play the other person. Rehearsal with a partner who never judges you.', 'Nervous about that conversation? Practice it right now.', 'You just rehearsed the hard part. The real thing will feel like the second take. 🎉', NULL);
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (4, 'office', 'The raise you''ve deserved for a year', 'You know the case for your raise. You''ve made it perfectly — in the shower, twice. But in front of your actual manager your polished points dissolve into "so I was wondering if maybe…" What you need isn''t a better argument. It''s reps.', 'Play my manager: busy, fair, allergic to surprises, watching a tight budget. I''m going to ask for a raise from [current] to [target]. Respond exactly as she would — one reply at a time, don''t go easy on me. If I type ''pause'', step out of the role and coach me on how I''m doing before we continue.', 'Tips inform; practice transforms. The character details (busy, fair, budget-conscious) make the rehearsal realistic, and the ''pause'' button gives you a coach inside the scrimmage — two tools in one prompt.');
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (4, 'shop', 'The rent conversation with your landlord', 'Your lease renewal is coming and the rumored increase would genuinely hurt. You have leverage — you''ve been a reliable tenant for years — but the conversation feels David-vs-Goliath. Practice being David with a script.', 'Play my commercial landlord. He''s businesslike, not hostile, and has other interested tenants — make him raise that. I want to negotiate my lease renewal: current rent [amount], rumored increase to [amount], my counter is [amount] citing [your reliability / market comparisons / improvements you''ve made]. Push back realistically, one reply at a time. Afterward, break character and tell me my strongest moment and my weakest one.', '"Give him real leverage" is what makes the practice honest — negotiating against a pushover teaches nothing. The post-game review (strongest/weakest moment) is where rehearsal becomes skill.');
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (4, 'parent', 'The talk your teenager keeps dodging', 'Grades slipping, phone glued, every attempt at conversation ends in a shrug or a slammed door. You get one real shot at this talk before it becomes A Whole Thing. Worth practicing on someone who can shrug convincingly.', 'Play my 15-year-old: smart, defensive, hates feeling lectured, answers in short sentences until they feel genuinely heard. I want to talk about [slipping grades / screen time] without it becoming a fight. Respond as they would, one reply at a time. If I say ''pause'', step out and tell me honestly whether I sounded like a partner or a prosecutor.', 'The prompt encodes the failure mode you fear ("lectured," "prosecutor") so the AI can catch you doing it — in the safe version of the conversation, where catching it costs nothing.');
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (4, 'job', 'The interview question you can''t wing', 'Interviews reward practice, and practicing into the mirror doesn''t push back. What you need is an interviewer who asks follow-ups — because follow-ups are where "winging it" goes to die.', 'Interview me for a [job title] role at a [type of company]. Ask one question at a time and wait for my answer. Follow up like a real interviewer would — dig into anything vague. Include one curveball I won''t expect. After 5 questions, break character and grade each answer: what landed, what to tighten, and the one answer I should rewrite word-for-word before the real thing.', 'One-question-at-a-time creates real pressure; asking for all ten at once creates a worksheet. The curveball request inoculates you against surprise itself — you''ve now had practice being surprised.');
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (4, 'retiree', 'The charge you''re disputing without the runaround', 'There''s a charge on your statement that shouldn''t be there, and you already know how the call goes: transfers, hold music, a script designed to outlast you. Practice the call until the script is yours, not theirs.', 'Play a customer service agent for [company] handling my dispute of a [amount] charge from [date] that I didn''t authorize. Be polite but follow a script: first deflect, then offer partial credit, only escalate if I''m firm and specific. One reply at a time. Help me practice staying courteous but immovable — and afterward, tell me the exact sentence that finally worked.', 'You''ve told AI to simulate the *system*, not just a person — deflection first, partial offer second. Beating the pattern in practice means recognizing it in real life, and "the sentence that finally worked" goes straight into your notes for the actual call.');
INSERT INTO challenge_rounds (mission_id, round, task, prompt_a, prompt_b, winner, verdict) VALUES (4, 1, 'preparing to ask for a raise.', 'Give me tips for asking for a raise.', 'Play my manager — busy, fair, hates surprises. I''m going to ask for a raise. Respond as she would, one reply at a time, and don''t go easy on me.', 'b', 'Tips are things you nod at and forget. A rehearsal is a thing that changes how you sound on Thursday. AI''s superpower isn''t knowing — it''s *playing along*.');
INSERT INTO challenge_rounds (mission_id, round, task, prompt_a, prompt_b, winner, verdict) VALUES (4, 2, 'practicing with an angry customer.', 'Act as a tough customer complaining about a late order. After we finish, break character and tell me what I did well and what I should do differently.', 'Act as a tough customer complaining about a late order.', 'a', 'Both get you a sparring partner — only A gets you a coach afterward. The debrief request is where practice turns into improvement; without it you''re just having a stressful chat on purpose.');
INSERT INTO challenge_rounds (mission_id, round, task, prompt_a, prompt_b, winner, verdict) VALUES (4, 3, 'mock job interview.', 'Interview me for a store manager job. Ask all 10 questions at once so I can prepare my answers.', 'Interview me for a store manager job. Ask one question, wait for my answer, then follow up like a real interviewer before moving on.', 'b', 'A produces a study sheet — useful, but it''s reading, not rehearsal. B recreates the thing that actually trips people up: thinking on your feet while someone digs into your vague answer.');
INSERT INTO challenge_rounds (mission_id, round, task, prompt_a, prompt_b, winner, verdict) VALUES (4, 4, 'the meeting with the school principal.', 'Play the school principal. I''m coming in to discuss a problem with my son''s teacher. Be realistic.', 'Play the school principal — and give her a real reason to resist me: policy, budget, loyalty to her staff. I''ll try to get to a yes anyway. If I say ''pause'', step out of character and coach me.', 'b', '"Be realistic" sounds right but leaves the AI free to be agreeably realistic — and practicing against a yes teaches nothing. B builds the wall first, then practices climbing it, with a coach on call. Design the resistance, not just the role.');
INSERT INTO missions (id, domain, title, skill, email_subject, win_message, note) VALUES (5, 'HOME', 'Fix the thing — or find out you shouldn''t touch it — before calling anyone.', 'Describe symptoms, answer AI''s questions, go step by step. A patient expert friend who never sighs at you.', 'That thing that''s broken? Let''s look at it together.', 'Diagnosed like a pro — and you knew exactly when to stop. 🎉', NULL);
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (5, 'parent', 'The washing machine that picked the worst week', 'The washing machine hums, clicks, and gives up — with a family''s worth of laundry mounting. A repair visit is $120 before parts. Ten minutes of smart diagnosis first can tell you whether this is a $6 fix or a real repair.', 'My washing machine fills and drains normally, but the drum won''t spin — it hums for a few seconds, clicks, then stops. It''s a [age]-year-old [brand] [front/top]-loader. List the likely causes from cheapest-to-fix to most expensive, tell me which I can safely check myself, exactly how to check each one — and which symptoms would mean ''stop, call a technician.''', 'Symptoms, not verdicts ("won''t spin, hums, clicks" — not "it''s broken"). "Cheapest first" orders the hunt the way a fair repairman would, and asking for the stop-signs keeps the confidence honest.');
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (5, 'shop', 'The fridge unit your margins depend on', 'The shop''s drinks fridge is running warm. If it dies, stock dies with it — but calling the technician for every hiccup burns money. What you need is triage: fix, watch, or call *now*.', 'The display fridge in my shop is reading [temp] instead of its usual [temp]. It''s a [brand/type], roughly [age] years old. Ask me one question at a time — noises, frost, airflow, door seals, whatever you need — then give me a triage verdict: something I can fix now, something to monitor overnight, or ''call a technician today.'' Include what stock to move and where, in the meantime.', '"Ask me one question at a time" turns AI into the diagnostician instead of you into the describer — it knows which questions matter and you don''t. The triage frame (fix / watch / call) is the actual business decision, so that''s the shape the answer should take.');
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (5, 'office', 'The dead-spot Wi-Fi that dies at 7pm', 'Video calls freeze in the exact room where you take them, and only in the evening. You''ve restarted the router like a good citizen. Time to actually diagnose it — no networking degree required.', 'My home Wi-Fi is fine everywhere except [room], and it gets worse around 7pm. Router is [type/age, if known], home is [apartment/house, size]. Ask me up to 5 questions to narrow it down, then give me fixes ranked from free to most expensive — and tell me the single cheapest test that would confirm the real cause before I buy anything.', 'The two clues you almost didn''t mention — *which room* and *what time* — are the whole diagnosis. "Cheapest test that confirms the cause before buying anything" is the sentence that saves you from the $200 gadget that fixes the wrong problem.');
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (5, 'job', 'Fix it for $6 instead of hiring it out', 'The dripping tap has hit the point where the sound bothers you and the water bill isn''t helping the budget. On a job-hunt budget, "call a plumber" is the last resort, not the first.', 'My [kitchen/bathroom] tap drips steadily from the spout even when fully closed. It''s a [single-lever / two-handle] tap. Walk me through fixing it one step at a time — after each step I''ll tell you what I see, and you adjust. Start with how to shut off the water. Tell me the parts I might need with rough prices, and warn me the moment we hit anything that could make things worse if I get it wrong.', 'Real repairs branch — what you find under the handle changes everything after it. One-step-at-a-time with report-backs is how an expert friend would guide you; all-steps-at-once is how instruction manuals end up soggy on the floor.');
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (5, 'retiree', 'The flickering light you''re right to be careful about', 'The hallway light has developed a flicker. You''re handy enough to be tempted and wise enough to hesitate — electricity is the one category where hesitating is a skill. So make the boundary the first question, not an afterthought.', 'My ceiling light flickers — [describe: constantly / when switched on / when someone walks upstairs]. Before anything else: tell me what I can check 100% safely without touching any wiring — bulb, switch behavior, pattern of when it happens. Then the likely causes, and be very clear about exactly where the safe checks end and the electrician begins. I''d rather call early than guess.', 'The best troubleshooting prompt asks where the edge is. AI matches the care you ask of it — demand the safety boundary up front and you get a cautious expert; skip it and you get a confident guide with no guardrails.');
INSERT INTO challenge_rounds (mission_id, round, task, prompt_a, prompt_b, winner, verdict) VALUES (5, 1, 'the broken washing machine.', 'My washing machine is broken. How do I fix it?', 'My washing machine fills and drains fine but the drum won''t spin — it hums a few seconds, then clicks off. 7-year-old front-loader. Likely causes, cheapest first?', 'b', '"Broken" tells AI nothing — symptoms are the language of diagnosis. And "cheapest first" turns a list of scary possibilities into a sensible order of operations.');
INSERT INTO challenge_rounds (mission_id, round, task, prompt_a, prompt_b, winner, verdict) VALUES (5, 2, 'the dying houseplant.', 'Ask me questions to figure out why my houseplant is dying — one at a time, then give me your diagnosis.', 'Why is my houseplant dying?', 'a', 'You don''t know which details matter — droopy or crispy? near a radiator? — but the interviewer does. When you can''t describe the problem well, don''t. Let AI run the interview.');
INSERT INTO challenge_rounds (mission_id, round, task, prompt_a, prompt_b, winner, verdict) VALUES (5, 3, 'unclogging the sink.', 'Walk me through unclogging my sink. Give me all the steps now.', 'Walk me through unclogging my sink one step at a time — I''ll tell you what I see after each step, and you adjust.', 'b', 'Repairs branch: what the first step reveals changes the third step. A recipe assumes; a conversation adapts. (Also: nobody scrolls a 14-step list with wet hands.)');
INSERT INTO challenge_rounds (mission_id, round, task, prompt_a, prompt_b, winner, verdict) VALUES (5, 4, 'the flickering ceiling light.', 'My ceiling light flickers. Give me a complete DIY guide to fix it, with a tools list.', 'My ceiling light flickers. Tell me what I can check safely without touching wiring, the likely causes — and exactly where DIY ends and the electrician begins.', 'b', 'A gets you a confident, complete, dangerous answer — completeness is not safety. The expert move is asking for the boundary. With anything that can hurt you, the best prompt is the one that knows when to stop.');
INSERT INTO missions (id, domain, title, skill, email_subject, win_message, note) VALUES (6, 'PAPERWORK & HEALTH ADMIN', 'Walk into your next appointment (or envelope) prepared.', 'Paste the real document — with personal details stripped out. Today''s mission includes the one safety habit we insist on.', 'The envelope you''ve been avoiding. Open it with backup.', 'Paperwork stopped being scary the moment you brought backup. 🎉', 'this mission teaches document-decoding and question-prep, never medical or legal advice — every version ends with better questions for the human professional, not a substitute for them.');
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (6, 'retiree', 'Fifteen minutes with the doctor, used well', 'Appointments are short and the important questions always surface in the car afterward. Tonight''s five minutes buys you a prepared fifteen tomorrow.', 'I have a [15]-minute appointment about [what''s going on — e.g., knee pain that''s lasted 2 months, worse on stairs]. Write the 5 questions that will get the most out of those minutes, ordered by importance. Then give me one clear opening sentence that tells the doctor the full picture fast — how long, what makes it better or worse, what I''m worried about. I''ll bring the list on paper.', 'The 15-minute constraint is the whole prompt — it forces prioritization, which is exactly what you can''t do while sitting on the exam table. The opening sentence matters most: doctors triage on it.');
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (6, 'parent', 'The school and medical forms that multiply', 'Permission slips, health histories, consent forms — each one written like a lease. Tonight''s pile has one that actually matters, and you want to understand it before signing it.', 'I''m pasting a form my child''s school sent — I''ve replaced names and ID numbers with [PLACEHOLDERS]. In plain language: what am I agreeing to, what am I giving permission for, and is there anything a careful parent would want to ask before signing? List the questions worth sending back, politely worded. Here''s the form: [paste]', 'Consent forms are written to be signed, not read — "what am I actually agreeing to" flips the reading direction. And you''ve just used the placeholder habit: real document, no real identifiers.');
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (6, 'office', 'Open enrollment, decoded before the deadline', 'Two health plans, one week to choose, and two brochures that seem designed to prevent comparison. This is a math problem wearing a trench coat — and math problems are delegable.', 'Compare these two health plan summaries — personal details removed: [paste both]. My situation: [rough number] doctor visits a year, [any regular prescriptions], and my main worry is [monthly cost vs. surprise bills]. Build a table of what I''d actually pay in a normal year and in a bad year on each plan, then tell me which worry each plan protects me from — and what question I should ask HR before deciding.', '"Normal year vs. bad year" is the comparison the brochures dodge, and naming your worry turns a generic comparison into *your* decision. Ending with a question for HR keeps the human in the loop where it counts.');
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (6, 'shop', 'The insurance renewal you sign without reading', 'Your business insurance renewal arrived: eleven pages, three changes buried somewhere, and a premium that went up. Signing unread is a gamble; reading it cover-to-cover isn''t happening. There''s a third option.', 'I''m pasting my business insurance renewal — policy numbers and personal details replaced with [PLACEHOLDERS]. Compare it against what I believe my current coverage is: [your rough understanding]. What changed, what''s no longer covered, and what''s new? Flag anything a small shop owner would regret not noticing, and draft 3 questions for my broker, ordered by how much money each answer could involve.', 'You gave AI both documents'' worth of context — the paper and your assumptions — so it can find the gap between them, which is where renewals hide their surprises. The broker questions ranked by money keeps the follow-up call short and sharp.');
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (6, 'job', 'The benefits package behind the salary', 'The offer letter came with a benefits PDF you skimmed past on the way to the salary number. But benefits are salary — sometimes thousands of dollars of it — and you have three days to ask questions while asking is still easy.', 'Here''s the benefits summary from my job offer — personal details removed: [paste]. Explain what each item is actually worth to me in plain money terms: [your rough age/situation, e.g., ''early 30s, no dependents, some student debt'']. Which two items are worth the most that people usually ignore? And write me 3 smart questions to email HR that make me look thorough, not difficult.', '"Worth to me in plain money terms" converts benefits-speak into the only unit you can compare. And the framing of the HR questions — thorough, not difficult — respects that you''re negotiating a relationship, not just a package.');
INSERT INTO challenge_rounds (mission_id, round, task, prompt_a, prompt_b, winner, verdict) VALUES (6, 1, 'the confusing doctor letter.', 'I got a letter from my doctor about test results. What do letters like this usually mean?', 'Explain this letter from my doctor in plain language, like you''d explain to a friend — I''ve removed my personal details: [paste letter].', 'b', 'A gets you a horoscope — generically true of letters in general, useless about yours. AI can only decode the document it can see. Paste the real thing.');
INSERT INTO challenge_rounds (mission_id, round, task, prompt_a, prompt_b, winner, verdict) VALUES (6, 2, 'preparing for an appointment.', 'What questions should I ask at a doctor appointment?', 'I have a 15-minute appointment about knee pain I''ve had for 2 months. Write the 5 questions that get the most from those minutes, ordered by importance — plus one opening sentence that gives the doctor the full picture fast.', 'b', 'The time limit is the prompt. Fifteen minutes forces ruthless prioritization, and that''s a job you can delegate tonight instead of failing at tomorrow.');
INSERT INTO challenge_rounds (mission_id, round, task, prompt_a, prompt_b, winner, verdict) VALUES (6, 3, 'choosing between two insurance plans.', 'Compare these two insurance plans: [paste both summaries].', 'Compare these two insurance plans: [paste both summaries]. I''m mostly worried about surprise bills. Show me what I''d pay in a normal year and in a bad year, as a table.', 'b', 'A produces a fair, balanced, useless summary of differences. B names the worry and the scenarios — turning a comparison into a decision. Fair isn''t the goal; *yours* is.');
INSERT INTO challenge_rounds (mission_id, round, task, prompt_a, prompt_b, winner, verdict) VALUES (6, 4, 'appealing a denied claim.', 'Here''s my insurance denial letter with my policy number and all my details: [paste everything]. Draft an appeal.', 'Here''s my insurance denial letter — I''ve replaced my policy number and personal details with [PLACEHOLDERS]. Draft an appeal I can fill in afterward.', 'b', 'The appeals come out identical — the difference is what you shared to get one. Personal identifiers add nothing to the drafting and don''t belong in any chat. Strip first, paste second, fill in after: the one habit from this whole week we insist on.');
INSERT INTO missions (id, domain, title, skill, email_subject, win_message, note) VALUES (7, 'FUN', 'Plan something delightful — and make the ideas earn it.', 'Constraints in, ten ideas out, then steer: "weirder," "cheaper," "combine 3 and 7." Brainstorming is a dial, not a slot machine.', 'Today''s mission is officially fun.', 'You just out-planned the person you were last weekend. 🎉', NULL);
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (7, 'parent', 'The rainy Saturday that''s coming for you', 'Forecast says rain, the kids'' energy says otherwise, and the museum-library-café circuit has been done to death. The problem isn''t a lack of ideas — it''s that the first five ideas are always the same five.', 'Rainy Saturday. Kids are [ages], budget [amount], we''ve exhausted [the usual suspects]. Give me 10 ideas ranked from calmest to most chaotic — nothing that needs buying special equipment. Then I''ll pick the two closest and you''ll combine them into something weirder.', 'Asking for *ten ranked* ideas forces AI past the obvious first five — the good stuff lives in ideas six through ten. And announcing the combine-and-weirder step up front sets up the real skill: steering.');
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (7, 'retiree', 'A surprise your grandkid will actually remember', 'Their birthday is coming and you refuse to default to the card-with-money again. The best gift you have is time and attention — what''s missing is the idea that packages it.', 'My grandchild is turning [age] and loves [their current obsessions]. Give me 10 ideas for a surprise experience with me they''d actually remember — ranked from simplest to most elaborate, budget under [amount]. No screens, nothing that needs me to be 30 again. Then take my favorite and build it out: what to prepare, and one small twist that makes it feel magic.', 'The constraints do the heavy lifting — "no screens," "nothing that needs me to be 30," the budget. Constraints aren''t limits on creativity; they''re the shape of it. The "small twist" request is where good becomes memorable.');
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (7, 'office', 'Date night, version 2.0', 'Somewhere along the way date night became dinner-and-a-show on autopilot. Fine is fine. But you''re one good brainstorm away from being the person who planned *that* night.', 'Plan a date night that isn''t dinner-and-a-movie. Context: [city/area], [budget], we like [a few honest interests], we''ve already done [the defaults]. Give me 10 ideas from cozy to ambitious. Then I''ll pick one and you''ll ask me 3 quick questions to tailor it — and give me the full plan including the one detail to arrange in advance that makes it feel effortless.', 'You''ve chained the week''s skills: constraints (Day 3), let-AI-ask (Day 1), then execution detail. "The one thing to arrange in advance" is the difference between a plan and a memory.');
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (7, 'shop', 'The event that makes your shop the story', 'Foot traffic is a habit you can create. One small in-shop event — done charmingly — gets locals talking, costs little, and beats another discount weekend. You just need the idea that fits your square footage.', 'I run a [type of shop] in [type of area]. Give me 10 small in-shop event ideas to bring locals in — budget under [amount], must run with just me and maybe one helper, no permits or chaos. Rank by effort. Then take the one I pick and turn it into a plan: timeline, a one-sentence announcement for the window and social media, and the little touch customers will tell their friends about.', 'The operational constraints (one person, no permits, small budget) filter out the Pinterest fantasies before they waste your time. Asking for the announcement sentence makes the idea instantly actionable — and "the little touch" is your word-of-mouth engine.');
INSERT INTO mission_content (mission_id, persona, story_title, story, prompt, why) VALUES (7, 'job', 'Fun that costs almost nothing (you''ve earned it)', 'Job hunting shrinks life to applications and waiting. A deliberately great, nearly-free day off isn''t slacking — it''s maintenance for the person doing the hunting. Plan it like it matters, because it does.', 'Design me a great day off for under [tiny amount] in [my area]. I like [honest interests]. 10 ideas, free ones first. Then build my favorite into a real plan with times — and include one small ''treat moment'' under $5, because the day should have a peak. End with zero guilt: one sentence on why rest is part of the job hunt.', '"Free ones first" is a sorting instruction that respects the constraint instead of apologizing for it. Engineering a "peak moment" is real psychology — days are remembered by their best minute — and yes, you can ask AI for the pep talk too.');
INSERT INTO challenge_rounds (mission_id, round, task, prompt_a, prompt_b, winner, verdict) VALUES (7, 1, 'the rainy Saturday.', 'Give me ideas for a fun Saturday with my kids.', 'Rainy Saturday, kids are 5 and 9, budget $20, we''ve done the museum and library to death. Give me 10 ideas ranked from calmest to most chaotic.', 'b', 'Constraints are creative fuel — "rainy, $20, not the museum" produces stranger, better ideas than a blank check. And asking for ten forces AI past the five you''d have thought of yourself.');
INSERT INTO challenge_rounds (mission_id, round, task, prompt_a, prompt_b, winner, verdict) VALUES (7, 2, 'the ideas were meh.', 'Numbers 3 and 7 are closest. Combine them, make it weirder, and give me 3 variations.', 'Those ideas are boring. Give me better ones.', 'a', 'B rerolls the slot machine and gets equally boring ideas in a different order. A steers — keep what''s closest, push a direction, ask for variations. A brainstorm is a dial, not a dice cup.');
INSERT INTO challenge_rounds (mission_id, round, task, prompt_a, prompt_b, winner, verdict) VALUES (7, 3, 'the anniversary surprise.', 'Plan a romantic surprise anniversary dinner at home, with a menu, timeline, and music suggestions.', 'Plan a surprise anniversary dinner at home. First ask me 5 quick questions — favorites, budget, allergies, our story — then give me the full plan: menu, day-before prep timeline, and a playlist.', 'b', 'Sound familiar? It''s Day 1''s reunion lesson wearing a nicer outfit: for anything personal, AI interviewing *you* first is what makes the result yours instead of a magazine''s. (If you got this one right — the week is working.)');
INSERT INTO challenge_rounds (mission_id, round, task, prompt_a, prompt_b, winner, verdict) VALUES (7, 4, 'the funny birthday poem.', 'Write a funny birthday poem for my coworker Dave.', 'Write a funny birthday poem for my coworker Dave. Material: he''s obsessed with his air fryer, quotes the same movie constantly, and lost to me at ping-pong 11–2 last week. Twelve lines, and it has to end with the score.', 'b', '"Funny" is not an instruction — material is. Comedy is specificity: the air fryer and the 11–2 are what make the room laugh, because the room knows Dave. AI brings the rhymes; you bring the Dave.');
